const data = $json;

const product = data.product;
const handlingCost = data.company_policy.handling_cost;

const refurbishNetRecovery =
  product.estimated_resale_value -
  product.refurbishment_cost_estimate -
  handlingCost;

const scrapRecovery =
  product.scrap_recovery_value;

const refurbishAdvantage =
  refurbishNetRecovery - scrapRecovery;

const refurbishmentEconomicallySensible =
  refurbishNetRecovery > 0 &&
  refurbishAdvantage >= 15;

const supplierWindowValid =
  Number(data.days_since_delivery) <=
  Number(product.supplier_return_window_days);

return [{
  json: {
    ...data,

    economics: {
      estimated_resale_value:
        product.estimated_resale_value,

      refurbishment_cost:
        product.refurbishment_cost_estimate,

      handling_cost:
        handlingCost,

      refurbish_net_recovery:
        Number(refurbishNetRecovery.toFixed(2)),

      scrap_recovery:
        product.scrap_recovery_value,

      refurbish_advantage_vs_scrap:
        Number(refurbishAdvantage.toFixed(2)),

      refurbishment_economically_sensible:
        refurbishmentEconomicallySensible,

      supplier_window_valid:
        supplierWindowValid
    }
  }
}];

const data = $json;

const product = data.product;

const condition =
  String(data.condition || "").toLowerCase();

const category =
  String(product.category || "").toLowerCase();

const originalPrice =
  Number(product.original_price);

const hardRules = [];

let forcedAction = null;
let requiresManualReview = false;

// Hygiene rule
if (
  category === "underwear" &&
  (
    condition.includes("used") ||
    condition.includes("stain") ||
    condition.includes("damage")
  )
) {
  hardRules.push({
    rule_id: "POL-002",
    message:
      "Used or compromised underwear cannot be returned to sale."
  });

  forcedAction = "SCRAP";
}

// High-value scrap protection
if (
  originalPrice > 100 &&
  (
    condition.includes("major damage") ||
    condition.includes("major stain")
  )
) {
  hardRules.push({
    rule_id: "POL-003",
    message:
      "High-value items cannot be automatically scrapped."
  });

  requiresManualReview = true;
}

// Perfect condition
if (
  condition === "perfect" &&
  String(data.tags_attached).toLowerCase() === "yes"
) {
  hardRules.push({
    rule_id: "POL-001",
    message:
      "Perfect condition with tags attached is eligible for restock."
  });
}

return [{
  json: {
    ...data,

    hard_rule_result: {
      matched_rules: hardRules,
      forced_action: forcedAction,
      requires_manual_review:
        requiresManualReview
    }
  }
}];

const d = $json;

const decisionContext = {
  company: d.company_policy.company,

  employee_observation: {
    return_id: d.return_id,
    sku: d.sku,
    condition: d.condition,
    condition_note: d.condition_note,
    tags_attached: d.tags_attached,
    packaging: d.packaging,
    days_since_delivery: d.days_since_delivery
  },

  product: d.product,

  economics: d.economics,

  hard_rule_result: d.hard_rule_result,

  company_policies: d.policy_match_result.matched_policies,

  allowed_actions:
    d.company_policy.allowed_actions
};

return [{
  json: {
    ...d,
    decision_context: decisionContext
  }
}];

const response = $json;

const original =
  $("Prepare Decision Context").first().json;

let content = response?.message?.content;

if (!content) {
  throw new Error("Ollama returned no message content.");
}

content = String(content)
  .trim()
  .replace(/^```json\s*/i, "")
  .replace(/^```\s*/i, "")
  .replace(/```$/i, "")
  .trim();

let parsed;

try {
  parsed = JSON.parse(content);
} catch (error) {
  return [{
    json: {
      ...original,
      ai_result: {
        parse_success: false,
        raw_response: content,
        error: error.message
      }
    }
  }];
}

return [{
  json: {
    ...original,
    ai_result: {
      parse_success: true,
      decision: parsed.decision,
      confidence: Number(parsed.confidence),
      reason: parsed.reason,
      matched_policy_ids: parsed.matched_policy_ids || [],
      economic_reasoning: parsed.economic_reasoning || "",
      requires_manual_review: Boolean(parsed.requires_manual_review)
    }
  }
}];

const d = $json;

const allowedActions = [
  "RESTOCK",
  "REFURBISH",
  "RETURN_TO_SUPPLIER",
  "SCRAP",
  "MANUAL_REVIEW"
];

let finalAction = d.ai_result?.decision;
let source = "AI_RECOMMENDATION";
let reason = d.ai_result?.reason;

// Find any learned policies that already matched this return case
const matchedPolicies =
  d.policy_match_result?.matched_policies || [];

const learnedPolicies = matchedPolicies.filter(policy =>
  String(policy.group || "").toUpperCase() === "LEARNED" &&
  allowedActions.includes(policy.preferred_action)
);

// --------------------------------------------------
// 1. AI FAILURE FALLBACK
// --------------------------------------------------

if (!d.ai_result?.parse_success) {
  finalAction = "MANUAL_REVIEW";
  source = "AI_FAILURE_FALLBACK";
  reason = "AI response could not be safely interpreted.";
}

// --------------------------------------------------
// 2. LEARNED POLICY
// Approved learned policies represent validated
// repeated human corrections.
// --------------------------------------------------

if (learnedPolicies.length > 0) {
  const learnedPolicy = learnedPolicies[0];

  finalAction = learnedPolicy.preferred_action;
  source = "LEARNED_POLICY";

  reason =
    `Approved learned policy applied: ${learnedPolicy.name}. ` +
    `This policy was created from repeated human corrections.`;
}

// --------------------------------------------------
// 3. HARD FORCED ACTION
// Hard rules override learned policies and AI.
// --------------------------------------------------

if (d.hard_rule_result?.forced_action) {
  finalAction = d.hard_rule_result.forced_action;
  source = "HARD_RULE";
  reason =
    "Deterministic company policy overrides other recommendations.";
}

// --------------------------------------------------
// 4. MANDATORY HARD-RULE REVIEW
// --------------------------------------------------

if (d.hard_rule_result?.requires_manual_review) {
  finalAction = "MANUAL_REVIEW";
  source = "HARD_RULE";
  reason =
    "Company policy requires human approval for this case.";
}

// --------------------------------------------------
// 5. FINAL ACTION VALIDATION
// --------------------------------------------------

if (!allowedActions.includes(finalAction)) {
  finalAction = "MANUAL_REVIEW";
  source = "VALIDATION_FALLBACK";
  reason =
    "Recommendation failed action validation.";
}

// --------------------------------------------------
// OUTPUT
// --------------------------------------------------

return [{
  json: {
    ...d,

    final_decision: {
      action: finalAction,
      source,
      reason,

confidence:
  source === "AI_RECOMMENDATION"
    ? d.ai_result?.confidence ?? null
    : null,

      economic_reasoning:
        d.ai_result?.economic_reasoning ?? "",

      matched_policy_ids:
        matchedPolicies.map(policy => policy.id),

      applied_learned_policy:
        source === "LEARNED_POLICY"
          ? {
              id: learnedPolicies[0].id,
              name: learnedPolicies[0].name,
              preferred_action:
                learnedPolicies[0].preferred_action
            }
          : null
    }
  }
}];

const system = $("Apply Final Decision Guardrails").first().json;
const review = $("Employee Review Decision").first().json;

const wasOverridden = review.Decision === "OVERRIDE";

let humanDecision = system.final_decision.action;
let overrideReason = "";

if (wasOverridden) {
  const override = $("Override Details").first().json;

  humanDecision = override["Override Action"];
  overrideReason = override["Override Reason"] || "";
}

// Remove duplicate policy IDs before saving
const matchedPolicyIds = [
  ...new Set(system.final_decision.matched_policy_ids || [])
];

// Preserve null when confidence does not apply
const systemConfidence =
  system.final_decision.confidence === null ||
  system.final_decision.confidence === undefined
    ? null
    : Number(system.final_decision.confidence);

return [{
  json: {
    return_id: system.return_id,
    sku: system.sku,
    product_name: system.product.product_name,
    category: system.product.category,

    condition: system.condition,
    condition_note: system.condition_note || "",

    system_decision: system.final_decision.action,
    system_confidence: systemConfidence,

    human_decision: humanDecision,
    was_overridden: wasOverridden,
    override_reason: overrideReason,

    decision_source: wasOverridden
      ? "HUMAN_OVERRIDE"
      : "HUMAN_ACCEPTED",

    matched_policy_ids: JSON.stringify(matchedPolicyIds),

    created_at: new Date().toISOString()
  }
}];

// All policy rows returned by the Data Table
const rows = $input.all().map(item => item.json);

// Recover the original return/product case
const original = $("Lookup Northstar Product").first().json;

function parseJSON(value, fallback) {
  if (value === null || value === undefined || value === "") {
    return fallback;
  }

  try {
    return typeof value === "string"
      ? JSON.parse(value)
      : value;
  } catch {
    return fallback;
  }
}

const policies = rows.map(row => ({
  id: row.policy_id,
  name: row.name,
  group: row.group,
  type: row.type,
  description: row.description,
  preferred_action: row.preferred_action,

  categories: parseJSON(row.categories, []),
  conditions: parseJSON(row.conditions, []),
  condition_keywords: parseJSON(row.condition_keywords, []),
  note_keywords: parseJSON(row.note_keywords, []),
  brand_tiers: parseJSON(row.brand_tiers, []),

  tags_attached:
    row.tags_attached === ""
      ? undefined
      : row.tags_attached === "true",

  requirements: parseJSON(row.requirements, {}),

  min_original_price:
    row.min_original_price === ""
      ? undefined
      : Number(row.min_original_price),

  max_estimated_resale_value:
    row.max_estimated_resale_value === ""
      ? undefined
      : Number(row.max_estimated_resale_value),

  min_estimated_resale_value:
    row.min_estimated_resale_value === ""
      ? undefined
      : Number(row.min_estimated_resale_value),

  max_days_since_delivery:
    row.max_days_since_delivery === ""
      ? undefined
      : Number(row.max_days_since_delivery)
}));

return [{
  json: {
    ...original,

    company_policy: {
      company: "Northstar Apparel",
      currency: "EUR",
      handling_cost: 4,

      allowed_actions: [
        "RESTOCK",
        "REFURBISH",
        "RETURN_TO_SUPPLIER",
        "SCRAP",
        "MANUAL_REVIEW"
      ],

      policies
    }
  }
}];

const d = $json;
const policies = d.company_policy?.policies || [];

const category = String(d.product?.category || "").toLowerCase();
const condition = String(d.condition || "").toLowerCase();
const note = String(d.condition_note || "").toLowerCase();
const brandTier = String(d.product?.brand_tier || "").toLowerCase();
const tags = String(d.tags_attached || "").toLowerCase() === "yes";

const econ = d.economics || {};

function containsAny(text, words = []) {
  return words.some(w =>
    text.includes(String(w).toLowerCase())
  );
}

const matched = policies.filter(p => {

  if (
    p.categories?.length &&
    !p.categories.map(x => String(x).toLowerCase()).includes(category)
  ) return false;

  if (
    p.brand_tiers?.length &&
    !p.brand_tiers.map(x => String(x).toLowerCase()).includes(brandTier)
  ) return false;

  if (
    p.conditions?.length &&
    !p.conditions.map(x => String(x).toLowerCase()).includes(condition)
  ) return false;

  if (
    p.condition_keywords?.length &&
    !containsAny(condition, p.condition_keywords)
  ) return false;

  if (
    p.note_keywords?.length &&
    !containsAny(note, p.note_keywords)
  ) return false;

  if (
    p.tags_attached !== undefined &&
    p.tags_attached !== tags
  ) return false;

if (p.requirements) {
  for (const [key, expected] of Object.entries(p.requirements)) {

    // Metadata about how a learned policy was created.
    // These fields describe provenance, not case-matching requirements.
    if (
      key === "learned_from_overrides" ||
      key === "occurrence_count" ||
      key === "previous_system_decision"
    ) {
      continue;
    }

    // Operational requirements such as economics/supplier-window checks
    if (econ[key] !== expected) return false;
  }
}

  if (
    p.min_original_price !== undefined &&
    Number(d.product.original_price) < p.min_original_price
  ) return false;

  if (
    p.max_estimated_resale_value !== undefined &&
    Number(d.product.estimated_resale_value) > p.max_estimated_resale_value
  ) return false;

  if (
    p.min_estimated_resale_value !== undefined &&
    Number(d.product.estimated_resale_value) < p.min_estimated_resale_value
  ) return false;

  if (
    p.max_days_since_delivery !== undefined &&
    Number(d.days_since_delivery) > p.max_days_since_delivery
  ) return false;

  return true;
});

return [{
  json: {
    ...d,
    policy_match_result: {
      total_policies: policies.length,
      matched_count: matched.length,
      matched_policies: matched
    }
  }
}];

const rows = $input.all().map(item => item.json);

// Remove duplicate return IDs
const unique = [
  ...new Map(rows.map(row => [row.return_id, row])).values()
];

// Group similar corrections
const groups = {};

for (const row of unique) {

  const key = [
    row.category,
    row.condition,
    row.system_decision,
    row.human_decision
  ].join("|").toLowerCase();

  if (!groups[key]) {
    groups[key] = {
      category: row.category,
      condition: row.condition,
      system_decision: row.system_decision,
      corrected_decision: row.human_decision,
      occurrence_count: 0,
      examples: []
    };
  }

  groups[key].occurrence_count++;

  groups[key].examples.push({
    return_id: row.return_id,
    sku: row.sku,
    condition_note: row.condition_note,
    override_reason: row.override_reason
  });
}

const patterns = Object.values(groups).map(pattern => ({
  ...pattern,

  // Require 3 separate returns before proposing policy
  candidate_rule_ready: pattern.occurrence_count >= 3
}));

return patterns.map(pattern => ({
  json: pattern
}));
